        /// <summary>Classe → classe MASTER equivalente (a árvore vale pra família toda).</summary>
        public static byte ToMasterClass(byte characterClass) => characterClass switch
        {
            0 or 2 or 3 => 3,      // DW/SM/GM
            4 or 6 or 7 => 7,      // DK/BK/BM
            8 or 10 or 11 => 11,   // ELF/ME/HE
            12 or 13 => 13,        // MG/DM
            16 or 17 => 17,        // DL/LE
            20 or 22 or 23 => 23,  // SUM/BS/DimM
            24 or 25 => 25,        // RF/FM
            _ => 0,
        };
